def comps(g,bg):
    seen=set(); res=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]==bg or (r,c) in seen: continue
            stack=[(r,c)]; cells=set([(r,c)])
            while stack:
                a,b=stack.pop()
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        x,y=a+dr,b+dc
                        if 0<=x<len(g) and 0<=y<len(g[0]) and g[x][y]!=bg and (x,y) not in seen and (x,y) not in cells:
                            stack.append((x,y)); cells.add((x,y))
            seen|=cells; res.append(cells)
    return res
