# Test hypothesis variants on the demo, checking which changes for the test grid
def variants(g):
    g=[r[:] for r in g]; H=len(g); W=len(g[0])
    def apply(skip_adj_4=False, draw_on_partial=False):
        out=[r[:] for r in g]
        for r in range(H):
            for c in range(W):
                v=g[r][c]
                if v==2 and skip_adj_4: continue
                if v==2:
                    cells=[(-1,-1),(0,-1),(1,-1),(1,0)]
                    placed=[]
                    for dr,dc in cells:
                        x,y=r+dr,c+dc
                        if 0<=x<H and 0<=y<W and g[x][y]==0:
                            out[x][y]=4; placed.append((x,y))
                    # draw on partial: keep what we can even if other cells hit non-bg
                    if draw_on_partial and len(placed)<4:
                        for dr,dc in [(-1,-1),(0,-1)]:
                            x,y=r+dr,c+dc
                            if 0<=x<H and 0<=y<W and g[x][y]==0: out[x][y]=4
                elif v==3:
                    x,y=r+1,c
                    if 0<=x<H and 0<=y<W and g[x][y]==0: out[x][y]=7
        return out
    return apply
