    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                st=[(i,j)];cells=set()
                while st:
                    a,b=st.pop()
                    if (a,b) in cells or not(0<=a<H and 0<=b<W) or g[a][b]==bg: continue
                    cells.add((a,b))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            st.append((a+dx,b+dy))
                seen|=cells;out.append(sorted(cells))
    return out
