G=load()
def comps(g,bg):
    H=len(g);W=len(g[0]);seen=set();out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and (i,j) not in seen:
                st=[(i,j)];cells=set()
                while st:
                    a,b=st.pop()
                    if (a,b) in cells or not(0<=a<H and 0<=b<W) or g[a][b]==bg: continue
                    cells.add((a,b))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            st.append((a+dx,b+dy))
                seen|=cells;out.append(sorted(cells))
    return out
def solve(g):
    H=len(g);W=len(g[0])
    bg=Cntr(x for r in g for x in r).most_common(1)[0][0]
    Cs=comps(g,bg)
    multi=[sorted(c) for c in Cs if len(c)>1]
    singles=sorted(next(iter(c)) for c in Cs if len(c)==1)
    out=[r[:] for r in g]
    def variants(pts):  # pts: list of ((a,b),c) ; return list of dicts {(a,b):c}
        cur=list(pts)
        res=[]
        for t in range(4):
            for fl in (False,True):
                w=[(a,-b,c) if fl else (a,b,c) for (a,b),c in cur]
                res.append(dict(w))
            cur=[(b,-a,c) for (a,b),c in cur]
        return res
    for m in singles:
        mv=g[m[0]][m[1]]
        best=None
        for C in multi:
            cm={}
            for p in C: cm[p]=g[p[0]][p[1]]
            for V in variants(list(cm.items())):
                anc=[cell for cell,v in V.items() if v==mv]
                if not anc: continue
                ax,ay=anc[0]
                s=tuple(sorted((x+m[0]-ax,y+m[1]-ay,c) for (x,y),c in V.items()))
                if not all(0<=x<H and 0<=y<W for x,y,_ in s): continue
                if any(out[x][y]!=bg for x,y,c in s if (x,y)!=(m[0],m[1])): continue
                key=(s[0],len(s))
                if best is None or key<best[0]: best=(key,s)
        if best:
            _,s=best
            for x,y,c in s: out[x][y]=c
    return out
for k in range(1,9):
    p=solve(G[f'Demo pair {k} input']); o=G[f'Demo pair {k} output']
    d=[(i,j,p[i][j],o[i][j]) for i in range(len(o)) for j in range(len(o[0])) if p[i][j]!=o[i][j]]
    print(k,'match' if not d else f'{len(d)} diffs',d[:5])
